    const int n_punti = 10;
    vector <double> y {0., 1.}; //vettore per eulero

    for (int i=0; i< n_punti; ++i){
        cout << "step size: " << error_step << endl;
        t = 0;
        x[0] = 0.;
        x[1] = 1.;
        y[0] = 0.;
